package android.view;public class KeyEvent {public static final int ACTION_DOWN=0,ACTION_UP=1,KEYCODE_ENTER=66,KEYCODE_DEL=67,KEYCODE_SPACE=62;private final int action,keyCode,unicode;public KeyEvent(int action,int code){this(action,code,code==KEYCODE_SPACE?32:0);}public KeyEvent(int action,int code,int unicode){this.action=action;keyCode=code;this.unicode=unicode;}public int getAction(){return action;}public int getKeyCode(){return keyCode;}public int getUnicodeChar(){return unicode;}}
